/*
 * A048686  Number of classes generated by function A007947 when applied to
 *          binomial coefficients.
 * https://oeis.org/A048686
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = number of distinct values of rad(C(n,k)) for 0 ≤ k ≤ n
 *            (rad is the product of distinct prime divisors)
 * Range:     u8 n <= 75, u16 n <= 75, u32 n <= 75, u64 n <= 75, u128 n <= 75,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

/* Forward declaration of the compare function for qsort */
static size_t g_words;               /* number of 64‑bit words per mask */

/* Compare two mask rows.
   The rows are pointers to uint64_t arrays of length g_words. */
static int compare_masks(const void *p1, const void *p2) {
    const uint64_t *const *a = (const uint64_t *const *)p1;
    const uint64_t *const *b = (const uint64_t *const *)p2;
    const uint64_t *ra = *a;
    const uint64_t *rb = *b;
    for (size_t w = 0; w < g_words; ++w) {
        if (ra[w] < rb[w]) return -1;
        if (ra[w] > rb[w]) return 1;
    }
    return 0;
}

seq_t a(idx_t n)
{
    /* ---------- 1. Prepare auxiliary structures ---------- */
    size_t N = (size_t)n;                 /* for array sizes (safe for n≤size_t max) */
    /* smallest prime factor */
    int *spf = (int *)malloc((N + 1) * sizeof(int));
    if (!spf) return 0;                   /* out of memory */
    for (size_t i = 0; i <= N; ++i) spf[i] = (int)i;
    for (size_t i = 2; i * i <= N; ++i) {
        if (spf[i] == (int)i) {
            for (size_t j = i * i; j <= N; j += i)
                if (spf[j] == (int)j) spf[j] = (int)i;
        }
    }

    /* list of primes up to n and mapping from prime → index */
    int *prime_index = (int *)malloc((N + 1) * sizeof(int));
    if (!prime_index) { free(spf); return 0; }
    for (size_t i = 0; i <= N; ++i) prime_index[i] = -1;
    int *primes = (int *)malloc((N + 1) * sizeof(int));   /* temporary buffer */
    if (!primes) { free(spf); free(prime_index); return 0; }
    size_t prime_cnt = 0;
    for (size_t i = 2; i <= N; ++i) if (spf[i] == (int)i) {
        prime_index[i] = (int)prime_cnt;
        primes[prime_cnt++] = (int)i;
    }

    g_words = (prime_cnt + 63) / 64;            /* number of 64‑bit words per mask */

    /* ---------- 2. Allocate masks and exponent array ---------- */
    uint64_t *masks = (uint64_t *)malloc((N + 1) * g_words * sizeof(uint64_t));
    if (!masks) { free(spf); free(prime_index); free(primes); return 0; }
    /* masks are initially zero-initialised by malloc? Not guaranteed, so zero them */
    memset(masks, 0, (N + 1) * g_words * sizeof(uint64_t));

    uint64_t **mask_rows = (uint64_t **)malloc((N + 1) * sizeof(uint64_t *));
    if (!mask_rows) { free(masks); free(spf); free(prime_index); free(primes); return 0; }
    for (size_t i = 0; i <= N; ++i)
        mask_rows[i] = masks + i * g_words;

    int *exp = (int *)calloc(prime_cnt, sizeof(int));   /* exponent of each prime in current binomial */
    if (!exp) { free(mask_rows); free(masks); free(spf); free(prime_index); free(primes); return 0; }

    /* ---------- 3. Build all masks for k = 0 … n ---------- */
    for (size_t k = 0; k < N; ++k) {
        /* Copy previous mask to the next row */
        memcpy(masks + (k + 1) * g_words, masks + k * g_words, g_words * sizeof(uint64_t));

        /* Multiply by (n - k), divide by (k + 1) */
        size_t num = N - k;
        size_t den = k + 1;
        uint64_t *row = masks + (k + 1) * g_words;    /* pointer to row k+1 */

        /* factorize numerator – multiply */
        while (num > 1) {
            int p = spf[num];
            size_t cnt = 0;
            while (num % (size_t)p == 0) {
                num /= (size_t)p;
                ++cnt;
            }
            size_t idx = (size_t)prime_index[p];
            size_t word = idx >> 6;
            size_t bit  = idx & 63;
            for (size_t j = 0; j < cnt; ++j) {
                exp[idx]++;
                if (exp[idx] == 1) row[word] |= (uint64_t)1 << bit;
            }
        }

        /* factorize denominator – divide */
        while (den > 1) {
            int p = spf[den];
            size_t cnt = 0;
            while (den % (size_t)p == 0) {
                den /= (size_t)p;
                ++cnt;
            }
            size_t idx = (size_t)prime_index[p];
            size_t word = idx >> 6;
            size_t bit  = idx & 63;
            for (size_t j = 0; j < cnt; ++j) {
                exp[idx]--;
                if (exp[idx] == 0) row[word] &= ~((uint64_t)1 << bit);
            }
        }
    }

    /* ---------- 4. Count distinct masks ---------- */
    qsort(mask_rows, N + 1, sizeof(uint64_t *), compare_masks);
    seq_t distinct = 1;   /* at least one mask (k = 0) */
    for (size_t i = 1; i <= N; ++i) {
        if (compare_masks(&mask_rows[i - 1], &mask_rows[i]) != 0)
            ++distinct;
    }

    /* ---------- 5. Clean up and return ---------- */
    free(exp);
    free(primes);
    free(prime_index);
    free(spf);
    free(mask_rows);
    free(masks);
    return distinct;
}
